insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.hero.subtitulo', 'apogesp', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$A voz coletiva de quem dedica a carreira a fazer a gestão pública de São Paulo funcionar melhor.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.quem-somos.label', 'apogesp', 3, 'text', $TXT$Quem somos — eyebrow$TXT$, $TXT$Sobre$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.quem-somos.titulo', 'apogesp', 4, 'text', $TXT$Quem somos — título$TXT$, $TXT$Quem Somos$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.quem-somos.texto', 'apogesp', 5, 'markdown', $TXT$Quem somos — parágrafos$TXT$, $TXT$A APOGESP nasceu de uma convicção simples: profissionais que compartilham uma missão precisam de um espaço para pensar juntos. Como entidade representativa dos Analistas de Políticas Públicas e Gestão Governamental do Município de São Paulo, a associação existe para amplificar o impacto coletivo da carreira.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.missao.label', 'apogesp', 6, 'text', $TXT$Missão — eyebrow$TXT$, $TXT$Propósito$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.missao.titulo', 'apogesp', 7, 'text', $TXT$Missão — título$TXT$, $TXT$Missão$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.missao.texto', 'apogesp', 8, 'markdown', $TXT$Missão — texto$TXT$, $TXT$Fortalecer a carreira de APPGG e contribuir para o aprimoramento da gestão pública no município de São Paulo — não com discursos, mas com produção técnica, representação institucional qualificada, articulação entre setores e investimento permanente em capacidades estatais. A missão da APOGESP é garantir que a experiência acumulada por seus integrantes se converta em memória, método e legado.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.objetivos.label', 'apogesp', 9, 'text', $TXT$Objetivos — eyebrow$TXT$, $TXT$Diretrizes$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.objetivos.titulo', 'apogesp', 10, 'text', $TXT$Objetivos — título$TXT$, $TXT$Objetivos$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.diretoria.label', 'apogesp', 11, 'text', $TXT$Diretoria — eyebrow$TXT$, $TXT$Gestão$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.diretoria.titulo', 'apogesp', 12, 'text', $TXT$Diretoria — título$TXT$, $TXT$Diretoria$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.independente.label', 'apogesp', 13, 'text', $TXT$Independente — eyebrow$TXT$, $TXT$Posicionamento$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.independente.titulo', 'apogesp', 14, 'text', $TXT$Independente — título$TXT$, $TXT$Uma Entidade Independente$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('apogesp.independente.texto', 'apogesp', 15, 'markdown', $TXT$Independente — parágrafos$TXT$, $TXT$A carreira de APPGG foi criada em 2015 e seus integrantes atuam vinculados à estrutura administrativa da Prefeitura de São Paulo. A APOGESP, por sua vez, é uma associação civil sem fins lucrativos, independente e autônoma — não integra a estrutura administrativa da Prefeitura, não depende do governo e não fala por ele.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.hero.label', 'carreira', 0, 'text', $TXT$Hero — eyebrow$TXT$, $TXT$A Carreira$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.hero.titulo', 'carreira', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Analistas de Políticas Públicas e Gestão Governamental$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.hero.subtitulo', 'carreira', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$A carreira que colabora — em conjunto com outras carreiras municipais e dentro das diretrizes da administração superior — para que São Paulo transforme intenções em entregas que mudam a realidade e promovem uma cidade mais pujante, justa e democrática.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.intro.label', 'carreira', 3, 'text', $TXT$Intro — eyebrow$TXT$, $TXT$Sobre$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.intro.titulo', 'carreira', 4, 'text', $TXT$Intro — título$TXT$, $TXT$O que é a carreira$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.intro.texto', 'carreira', 5, 'markdown', $TXT$Intro — parágrafos$TXT$, $TXT$Em 2015, o município de São Paulo fez uma aposta: criar uma carreira de nível superior dedicada a colaborar com o fortalecimento da capacidade do governo municipal de planejar, implementar e avaliar políticas públicas. A Lei Municipal nº 16.193 deu nome a essa aposta — Analista de Políticas Públicas e Gestão Governamental — e definiu suas atribuições: implementação, supervisão, coordenação, execução, monitoramento e avaliação de projetos, atividades e políticas públicas, sempre em apoio às prioridades fixadas pela administração superior.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.citacao.frase', 'carreira', 6, 'markdown', $TXT$Citação$TXT$, $TXT$A força da carreira está em colaborar, dentro da legalidade e das prioridades da administração superior, para que cada política pública chegue ao cidadão com técnica, integridade e continuidade.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.citacao.autor', 'carreira', 7, 'text', $TXT$Citação — autor$TXT$, $TXT$Odilon A. Candido — Diretor Jurídico da APOGESP$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.perfil.label', 'carreira', 8, 'text', $TXT$Perfil — eyebrow$TXT$, $TXT$Perfil$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.perfil.titulo', 'carreira', 9, 'text', $TXT$Perfil — título$TXT$, $TXT$Quem São os APPGGs$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.perfil.texto', 'carreira', 10, 'markdown', $TXT$Perfil — parágrafos$TXT$, $TXT$Administradores públicos, economistas, cientistas sociais, engenheiros, advogados — os APPGGs chegam de formações diversas, mas convergem em uma competência comum: a capacidade de traduzir problemas complexos em decisões implementáveis. O ingresso ocorre por concurso público de provas e títulos, exigindo nível superior.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.areas.label', 'carreira', 11, 'text', $TXT$Áreas — eyebrow$TXT$, $TXT$Competências$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.areas.titulo', 'carreira', 12, 'text', $TXT$Áreas — título$TXT$, $TXT$Áreas de Atuação$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.memoria.label', 'carreira', 13, 'text', $TXT$Memória — eyebrow$TXT$, $TXT$Continuidade$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.memoria.titulo', 'carreira', 14, 'text', $TXT$Memória — título$TXT$, $TXT$Memória Institucional das Políticas Públicas$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.memoria.texto', 'carreira', 15, 'markdown', $TXT$Memória — parágrafos$TXT$, $TXT$Governos passam, ciclos políticos se sucedem, secretários chegam e partem. O que permanece — e o que sustenta a capacidade de São Paulo de governar a si mesma — é o conhecimento acumulado sobre como cada política pública foi pensada, executada e revisada ao longo do tempo. Os APPGGs são, em larga medida, responsáveis por preservar essa continuidade.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.cronologia.label', 'carreira', 16, 'text', $TXT$Cronologia — eyebrow$TXT$, $TXT$Cronologia$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.cronologia.titulo', 'carreira', 17, 'text', $TXT$Cronologia — título$TXT$, $TXT$Uma Década em Construção$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.numeros.label', 'carreira', 18, 'text', $TXT$Números — eyebrow$TXT$, $TXT$Dados$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.numeros.titulo', 'carreira', 19, 'text', $TXT$Números — título$TXT$, $TXT$APPGGs em Números$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.numeros.legenda', 'carreira', 20, 'text', $TXT$Números — legenda$TXT$, $TXT$Snapshot fevereiro de 2026$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.legal.label', 'carreira', 21, 'text', $TXT$Marco legal — eyebrow$TXT$, $TXT$Legislação$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.legal.titulo', 'carreira', 22, 'text', $TXT$Marco legal — título$TXT$, $TXT$Marco Legal$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('carreira.legal.texto', 'carreira', 23, 'markdown', $TXT$Marco legal — parágrafos$TXT$, $TXT$A base legal da carreira está no artigo 13 da Lei nº 16.193/2015, que define suas atribuições como: *“implementação, supervisão, coordenação, execução, monitoramento e avaliação de projetos, atividades e políticas públicas da Administração Direta e Indireta da Prefeitura do Município de São Paulo.”* Poucas carreiras municipais no Brasil têm um mandato tão amplo — e tão exigente.
