insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.hero.titulo', 'atuacao', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Atuação dos APPGGs$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.hero.subtitulo', 'atuacao', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Mais de 50 casos de colaboração de Analistas de Políticas Públicas e Gestão Governamental com órgãos e equipes da Prefeitura de São Paulo. Do Caderno Gestão Pública em Rede ao 2º Seminário APPGG.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.casos.label', 'atuacao', 3, 'text', $TXT$Casos — eyebrow$TXT$, $TXT$Casos Documentados$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.casos.titulo', 'atuacao', 4, 'text', $TXT$Casos — título$TXT$, $TXT$Onde a Carreira Colaborou$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.casos.subtitulo', 'atuacao', 5, 'text', $TXT$Casos — subtítulo$TXT$, $TXT$Cada caso abaixo registra contribuições de APPGGs em iniciativas conduzidas em conjunto com outras carreiras, gestores e parceiros institucionais, dentro das prioridades fixadas pela administração superior.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('atuacao.eixos.label', 'atuacao', 6, 'text', $TXT$Eixos — eyebrow$TXT$, $TXT$Vocação$TXT$) on conflict (key) do nothing;
