insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.hero.label', 'contato', 0, 'text', $TXT$Hero — eyebrow$TXT$, $TXT$Fale Conosco$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.hero.titulo', 'contato', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Contato$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.hero.subtitulo', 'contato', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Se você é servidor, pesquisador, gestor ou cidadão interessado em gestão pública municipal, este é o canal.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.info.label', 'contato', 3, 'text', $TXT$Info — eyebrow$TXT$, $TXT$Informações$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.info.titulo', 'contato', 4, 'text', $TXT$Info — título$TXT$, $TXT$Como nos encontrar$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.info.email', 'contato', 5, 'text', $TXT$E-mail$TXT$, $TXT$apogesp@gmail.com$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.info.localizacao', 'contato', 6, 'text', $TXT$Localização$TXT$, $TXT$São Paulo — SP, Brasil$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('contato.info.texto', 'contato', 7, 'markdown', $TXT$Info — texto final$TXT$, $TXT$A APOGESP recebe mensagens de associados, gestores públicos, pesquisadores, jornalistas e de qualquer cidadão interessado na carreira de APPGG e na gestão pública municipal de São Paulo. Respondemos em até cinco dias úteis.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.hero.label', 'diversidade', 0, 'text', $TXT$Hero — eyebrow$TXT$, $TXT$Diversidade$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.hero.titulo', 'diversidade', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Representar a cidade ainda é uma agenda em disputa$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.hero.subtitulo', 'diversidade', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$A APOGESP olha para a composição da carreira sem complacência. Os números mostram avanços, mas também distâncias persistentes em relação à cidade que administramos — e oscilações entre concursos que contradizem qualquer narrativa de progresso automático. Diversidade não se corrige por inércia: depende de regras de ingresso, critérios de promoção, abertura a posições decisórias e disposição institucional para revisar o que está naturalizado.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.panorama.label', 'diversidade', 3, 'text', $TXT$Panorama — eyebrow$TXT$, $TXT$Panorama$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.panorama.titulo', 'diversidade', 4, 'text', $TXT$Panorama — título$TXT$, $TXT$O retrato — e o que ele cobra$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.label', 'diversidade', 5, 'text', $TXT$Contexto — eyebrow$TXT$, $TXT$Contexto$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.titulo', 'diversidade', 6, 'text', $TXT$Contexto — título$TXT$, $TXT$A neutralidade administrativa é uma ficção conveniente$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.subtitulo', 'diversidade', 7, 'text', $TXT$Contexto — subtítulo$TXT$, $TXT$Critérios de elegibilidade, modelos de atendimento, fluxos de aprovação e bases de dados raramente são neutros em seus efeitos. Quando o corpo técnico que os formula reproduz uma única perspectiva social, a administração tende a confundir suas próprias zonas cegas com universalidade — e a tratar como exceção o que é, na verdade, exclusão sistemática.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.bloco1-titulo', 'diversidade', 8, 'text', $TXT$Contexto — bloco 1 título$TXT$, $TXT$Exclusão sem autoria explícita$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.bloco1-texto', 'diversidade', 9, 'markdown', $TXT$Contexto — bloco 1 texto$TXT$, $TXT$Políticas públicas não falham apenas por má-fé ou subfinanciamento. Falham, com frequência, em decisões aparentemente técnicas: o documento exigido, o canal eleito como padrão, o horário de atendimento, o indicador escolhido para medir sucesso. Cada uma dessas escolhas filtra quem acessa, quem é contado e quem permanece invisível. Sem diversidade no desenho, o filtro opera no automático.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.bloco2-titulo', 'diversidade', 10, 'text', $TXT$Contexto — bloco 2 título$TXT$, $TXT$Onde a diretriz se perde$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.bloco2-texto', 'diversidade', 11, 'markdown', $TXT$Contexto — bloco 2 texto$TXT$, $TXT$Entre o discurso de equidade e o efeito concreto no território existe uma cadeia longa de decisões técnicas. É nessa cadeia — operada por gestores como o APPGG — que prioridades viram procedimentos e procedimentos viram acesso (ou barreira). Tratar essa camada como neutra é o que permite que governos defendam pautas progressistas enquanto suas burocracias seguem produzindo desigualdade.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.contexto.destaque', 'diversidade', 12, 'markdown', $TXT$Contexto — destaque$TXT$, $TXT$Para a APOGESP, burocracia representativa não é concessão simbólica nem cota a tolerar. É uma exigência técnica: ampliar repertórios de análise no Estado é o que permite identificar exclusões antes que elas se consolidem em política pública.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.atuacao.label', 'diversidade', 13, 'text', $TXT$Atuação — eyebrow$TXT$, $TXT$Atuação estratégica$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.atuacao.titulo', 'diversidade', 14, 'text', $TXT$Atuação — título$TXT$, $TXT$Onde o APPGG faz diferença$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.atuacao.subtitulo', 'diversidade', 15, 'text', $TXT$Atuação — subtítulo$TXT$, $TXT$O APPGG não apenas executa políticas. Ele desenha, ajusta, mede e corrige. Em cada uma dessas funções, diversidade e capacidade técnica podem se reforçar mutuamente.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.lideranca.label', 'diversidade', 16, 'text', $TXT$Liderança — eyebrow$TXT$, $TXT$Liderança$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.lideranca.titulo', 'diversidade', 17, 'text', $TXT$Liderança — título$TXT$, $TXT$Quem decide ainda não reflete quem entra$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.lideranca.subtitulo', 'diversidade', 18, 'text', $TXT$Liderança — subtítulo$TXT$, $TXT$A presença de mulheres e pessoas negras em cargos de liderança é um dos testes mais duros da maturidade institucional. Os números abaixo mostram avanços relativos — mulheres e pessoas negras estão proporcionalmente mais presentes na liderança do que na carreira como um todo. Mas isso não autoriza autocomplacência: liderança ainda é majoritariamente branca e masculina, e o acesso a essas posições segue dependente de redes informais que a APOGESP entende como objeto legítimo de escrutínio.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.evolucao.label', 'diversidade', 19, 'text', $TXT$Evolução — eyebrow$TXT$, $TXT$Evolução$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.evolucao.titulo', 'diversidade', 20, 'text', $TXT$Evolução — título$TXT$, $TXT$O progresso não é linear — e os dados mostram$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.evolucao.subtitulo', 'diversidade', 21, 'text', $TXT$Evolução — subtítulo$TXT$, $TXT$A leitura honesta das coortes desautoriza qualquer narrativa de avanço automático. A representatividade racial caiu da geração pioneira (37,5%) para os concursos de 2021–2022 (29,2%) e 2024 (25,5%), recuperando-se em parte em 2026 (35,3%) — ainda abaixo do patamar inicial e muito distante da composição racial da cidade. Cada concurso é uma decisão política sobre quem o Estado escolhe formar.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.evolucao.destaque', 'diversidade', 22, 'markdown', $TXT$Evolução — destaque$TXT$, $TXT$A oscilação entre coortes não é detalhe estatístico: é evidência de que regras de seleção, políticas afirmativas, formato das provas e critérios de pontuação produzem efeitos diretos e mensuráveis na composição do serviço público. Tratar a diversidade do ingresso como agenda permanente — e não como bandeira a hastear em ano par — é responsabilidade institucional. A APOGESP cobra essa continuidade.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.presenca.label', 'diversidade', 23, 'text', $TXT$Presença — eyebrow$TXT$, $TXT$Presença institucional$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.presenca.titulo', 'diversidade', 24, 'text', $TXT$Presença — título$TXT$, $TXT$Distribuição desigual entre os órgãos$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.presenca.destaque', 'diversidade', 25, 'markdown', $TXT$Presença — destaque$TXT$, $TXT$Distribuição importa porque concentração é, por definição, ausência em outro lugar. Acompanhar onde a diversidade está — e onde ela falta — é parte do trabalho de uma associação que leva a sério a representatividade do corpo técnico que ajuda a decidir o orçamento, o planejamento e as políticas da cidade.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.fechamento.label', 'diversidade', 26, 'text', $TXT$Fechamento — eyebrow$TXT$, $TXT$Posição da APOGESP$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.fechamento.titulo', 'diversidade', 27, 'text', $TXT$Fechamento — título$TXT$, $TXT$Reconhecer o avanço sem dispensar a cobrança$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('diversidade.fechamento.texto', 'diversidade', 28, 'markdown', $TXT$Fechamento — parágrafos$TXT$, $TXT$Os dados desta página descrevem uma carreira que avançou — e que segue devendo. A presença de mulheres e de pessoas negras melhorou em relação a outras carreiras de Estado, mas continua aquém da composição de São Paulo. A inclusão de pessoas com deficiência permanece marginal. A liderança ainda é majoritariamente branca e masculina. E o ingresso, longe de uma trajetória ascendente, oscila concurso a concurso, em função de regras que mudam, políticas afirmativas que enfraquecem e prioridades que se deslocam.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.hero.label', 'sustentabilidade', 0, 'text', $TXT$Hero — eyebrow$TXT$, $TXT$Meio Ambiente$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.hero.titulo', 'sustentabilidade', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Sustentabilidade$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.hero.subtitulo', 'sustentabilidade', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Como os APPGGs colaboram com a construção de uma São Paulo mais sustentável, sempre em parceria com outras carreiras e dentro das diretrizes da administração superior.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.intro.texto', 'sustentabilidade', 3, 'markdown', $TXT$Intro — parágrafos$TXT$, $TXT$São Paulo é a maior metrópole da América Latina — e também uma das mais vulneráveis às mudanças climáticas. Enchentes, ilhas de calor, crises hídricas e poluição atmosférica são desafios que exigem políticas públicas sofisticadas, baseadas em evidências e com visão de longo prazo.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.eixos.label', 'sustentabilidade', 4, 'text', $TXT$Eixos — eyebrow$TXT$, $TXT$Eixos Temáticos$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.eixos.titulo', 'sustentabilidade', 5, 'text', $TXT$Eixos — título$TXT$, $TXT$Onde os APPGGs colaboram com a sustentabilidade$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.visao.label', 'sustentabilidade', 6, 'text', $TXT$Visão — eyebrow$TXT$, $TXT$Perspectiva$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.visao.titulo', 'sustentabilidade', 7, 'text', $TXT$Visão — título$TXT$, $TXT$Uma cidade que planeja seu futuro$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.visao.texto', 'sustentabilidade', 8, 'markdown', $TXT$Visão — texto$TXT$, $TXT$A agenda ambiental não é um tema isolado — ela atravessa todas as áreas da gestão pública. Saúde, mobilidade, habitação, educação: cada política setorial tem uma dimensão ambiental que precisa ser considerada. Os APPGGs, por sua formação transversal e capacidade de articulação, colaboram — em conjunto com as carreiras técnicas finalísticas e sob coordenação das lideranças de cada pasta — para que a sustentabilidade seja tratada como eixo estruturante dentro dos Planos de Atuação Institucional.
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('sustentabilidade.cta.texto', 'sustentabilidade', 9, 'text', $TXT$CTA — texto$TXT$, $TXT$Conheça os Planos de Atuação Institucional dos órgãos com projetos ambientais$TXT$) on conflict (key) do nothing;
