insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.hero.label', 'campanha-salarial', 0, 'text', $TXT$Hero — eyebrow$TXT$, $TXT$Campanha 2026$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.hero.titulo', 'campanha-salarial', 1, 'text', $TXT$Hero — título$TXT$, $TXT$Remuneração Justa para Quem Constrói a Cidade$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.hero.subtitulo', 'campanha-salarial', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Uma carreira estratégica não sobrevive com remuneração defasada. Conheça os números, compare com o governo federal e com outros municípios — e entenda por que a recomposição salarial dos APPGGs é urgente.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.problema.label', 'campanha-salarial', 3, 'text', $TXT$Problema — eyebrow$TXT$, $TXT$O Problema$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.problema.titulo', 'campanha-salarial', 4, 'text', $TXT$Problema — título$TXT$, $TXT$Uma Década Sem Equiparação$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.problema.subtitulo', 'campanha-salarial', 5, 'text', $TXT$Problema — subtítulo$TXT$, $TXT$Em 2015, a carreira de APPGG foi criada como espelho municipal do EPPGG federal. Dez anos depois, a remuneração não acompanhou — nem o governo federal, nem municípios como Niterói.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.comparativo.label', 'campanha-salarial', 6, 'text', $TXT$Comparativo — eyebrow$TXT$, $TXT$Comparativo$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.comparativo.titulo', 'campanha-salarial', 7, 'text', $TXT$Comparativo — título$TXT$, $TXT$O Mesmo Trabalho, Três Realidades$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.comparativo.subtitulo', 'campanha-salarial', 8, 'text', $TXT$Comparativo — subtítulo$TXT$, $TXT$Remuneração por nível de progressão na carreira. APPGG (São Paulo), EPPGG (Federal, 2026) e APPGG (Niterói, com gratificação de 50%).$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.comparativo.fontes', 'campanha-salarial', 9, 'text', $TXT$Comparativo — fontes$TXT$, $TXT$Fontes: Lei nº 18.235/2025 (APPGG SP); MP nº 1.286/2024 (EPPGG Federal); Diário Oficial de Niterói, 28/11/2025 (APPGG Niterói, com gratificação de desempenho de 50%).$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.comparativo.sintese', 'campanha-salarial', 10, 'markdown', $TXT$Comparativo — síntese$TXT$, $TXT$O APPGG de São Paulo — maior metrópole da América Latina — recebe **27% menos** que o cargo equivalente em Niterói e **34% menos** que o EPPGG federal no início da carreira. No topo, a defasagem frente ao governo federal chega a **56%**.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-salarial.cta.frase', 'campanha-salarial', 11, 'text', $TXT$CTA — frase$TXT$, $TXT$Não se trata de privilégio. Trata-se de reter os profissionais que a cidade precisa para funcionar.$TXT$) on conflict (key) do nothing;
