insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.hero.titulo', 'campanha-nomeacao', 1, 'text', $TXT$Hero — título$TXT$, $TXT$53 Aprovados. Zero Razões Para Esperar.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.hero.subtitulo', 'campanha-nomeacao', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Um concurso com 242 candidatos por vaga selecionou os melhores. 80 já servem a cidade. Faltam 53 — e 102 cargos vagos esperando por eles.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.narrativa.texto', 'campanha-nomeacao', 3, 'markdown', $TXT$Narrativa — parágrafos$TXT$, $TXT$Em 2023, a Lei nº 17.913 ampliou o quadro de APPGGs para **300 cargos** — um reconhecimento de que São Paulo precisa de mais analistas de gestão. Hoje, **102 desses cargos estão vagos**. Um terço da capacidade projetada simplesmente não existe.
