insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.timeline.subtitulo', 'campanha-nomeacao', 13, 'text', $TXT$Timeline — subtítulo$TXT$, $TXT$Todas as fases foram cumpridas. Resta apenas o ato administrativo da nomeação.$TXT$) on conflict (key) do nothing;
