insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.viabilidade.titulo', 'campanha-nomeacao', 15, 'text', $TXT$Viabilidade — título$TXT$, $TXT$O Custo da Nomeação é Marginal$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.viabilidade.texto', 'campanha-nomeacao', 16, 'markdown', $TXT$Viabilidade — texto$TXT$, $TXT$Frente a um orçamento municipal de **R$ 135 bilhões** e uma despesa de pessoal de **R$ 44 bilhões**, o investimento na nomeação dos 53 aprovados representa uma fração ínfima — com retorno imediato em capacidade de gestão, qualidade técnica e entrega de resultados para a população.$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('campanha-nomeacao.cta.frase', 'campanha-nomeacao', 17, 'text', $TXT$CTA — frase$TXT$, $TXT$Cada APPGG não nomeado é uma política pública que será coordenada com menos rigor, monitorada com menos precisão e avaliada com menos profundidade.$TXT$) on conflict (key) do nothing;
