insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('publicacoes.hero.subtitulo', 'publicacoes', 2, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$O que a carreira de APPGG pensa, documenta e publica. Artigos, notas técnicas e propostas.$TXT$) on conflict (key) do nothing;
