insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('publicacoes.destaque.titulo', 'publicacoes', 4, 'text', $TXT$Destaque — título$TXT$, $TXT$Caderno Gestão Pública em Rede — 1ª Edição$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('publicacoes.destaque.texto', 'publicacoes', 5, 'markdown', $TXT$Destaque — texto$TXT$, $TXT$Nove artigos. Nove histórias de quem esteve dentro da máquina pública, tentando fazê-la funcionar melhor. A primeira publicação coletiva dos APPGGs celebra uma década de carreira com o que ela faz de melhor: análise rigorosa, experiência de campo e compromisso com o registro. Organizado pela Assessoria de Carreiras Transversais (ACT) da Secretaria Municipal de Gestão.$TXT$) on conflict (key) do nothing;
