insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('planos-atuacao.hero.titulo', 'planos-atuacao', 0, 'text', $TXT$Hero — título$TXT$, $TXT$Planos de Atuação Institucional$TXT$) on conflict (key) do nothing;
insert into public.page_fields (key, pagina, ordem, tipo, descricao, value_publicado) values ('planos-atuacao.hero.subtitulo', 'planos-atuacao', 1, 'text', $TXT$Hero — subtítulo$TXT$, $TXT$Os PAIs formalizam a demanda de cada órgão por APPGGs, detalhando projetos estratégicos, resultados esperados e competências necessárias. Conheça onde e como os analistas contribuem para a modernização da gestão pública em São Paulo.$TXT$) on conflict (key) do nothing;
